// Fig. 2.1 modernized: fig02_01.cpp
// Text-printing program demonstrating basic C++ structure.
#include <iostream> // allows program to output data to the screen

// function main begins program execution
int main() {
   std::cout << "Welcome to C++!\n"; // display message

   return 0; // indicate that program ended successfully
} // end function main

// Fig. 2.1 compliant format demonstration
// Demonstrating three-space indentation, comments, and stream output
#include <iostream>

int main()
{
   // Indented exactly three spaces inside function body
   std::cout << "Testing C++ indentation and statement termination.\n";
   std::cout << "Return code 0 indicates success.\n";

   return 0; // explicit exit code indicating successful termination
} // end function main
